import sys

def main():
    data = sys.stdin.buffer.read().split()
    N, M = int(data[0]), int(data[1])
    S = data[2].decode()
    MOD = 998244353
    size = 1 << N
    distinct = sorted(set(S))
    rest = 26 - len(distinct)

    trans = []
    for mask in range(size):
        d = [0] * (N + 1)
        for j in range(1, N + 1):
            d[j] = d[j-1] + ((mask >> (j-1)) & 1)
        m = {}
        for c in distinct:
            d2 = [0] * (N + 1)
            for j in range(1, N + 1):
                b = d2[j-1]
                v = d[j-1] + (1 if S[j-1] == c else 0)
                if v > b:
                    b = v
                if d[j] > b:
                    b = d[j]
                d2[j] = b
            m2 = 0
            for j in range(1, N + 1):
                if d2[j] == d2[j-1] + 1:
                    m2 |= 1 << (j-1)
            m[m2] = m.get(m2, 0) + 1
        if rest:
            m[mask] = m.get(mask, 0) + rest
        trans.append(list(m.items()))

    dp = [0] * size
    dp[0] = 1
    for _ in range(M):
        ndp = [0] * size
        for mask in range(size):
            v = dp[mask]
            if v:
                for tgt, mult in trans[mask]:
                    ndp[tgt] = (ndp[tgt] + v * mult) % MOD
        dp = ndp

    ans = [0] * (N + 1)
    for mask in range(size):
        v = dp[mask]
        if v:
            k = bin(mask).count('1')
            ans[k] = (ans[k] + v) % MOD

    sys.stdout.write(' '.join(map(str, ans)) + '\n')

main()

import sys

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    a = list(map(int, data[1:1+n]))
    last = {}
    ans = float('inf')
    for i, v in enumerate(a):
        if v in last:
            gap = i - last[v] + 1
            if gap < ans:
                ans = gap
        last[v] = i
    print(ans if ans != float('inf') else -1)

