import sys
import math

def main():
    N = int(sys.stdin.readline())

    # integer cube root of N
    lim = int(round(N ** (1.0 / 3.0)))
    while (lim + 1) ** 3 <= N:
        lim += 1
    while lim ** 3 > N:
        lim -= 1

    for d in range(1, lim + 1):
        if N % d != 0:
            continue
        M = N // d
        # x = y + d, N = d*(3y^2 + 3dy + d^2) = d*M
        # 12*M - 3*d^2 must be a perfect square s^2 with s = 6y + 3d
        val = 12 * M - 3 * d * d
        if val <= 0:
            continue
        s = math.isqrt(val)
        if s * s != val:
            continue
        if s <= 3 * d:
            continue
        if (s - 3 * d) % 6 != 0:
            continue
        y = (s - 3 * d) // 6
        x = y + d
        if x > 0 and y > 0 and x * x * x - y * y * y == N:
            print(x, y)
            return

    print(-1)

main()

